TMap<class FString, float> UPrimitiveStatsProfilingHelper::CapturePrimitiveValues(const TMap<class FString, float>& InPrevCapture, TMap<class FString, float>* OutComparison, const TArray<class FString>& DesiredStats)
{
	static class UFunction* Func = nullptr;

	if (Func == nullptr)
		Func = StaticClass()->GetFunction("PrimitiveStatsProfilingHelper", "CapturePrimitiveValues");

	Params::PrimitiveStatsProfilingHelper_CapturePrimitiveValues Parms{};

	Parms.InPrevCapture = std::move(InPrevCapture);
	Parms.DesiredStats = std::move(DesiredStats);

	auto Flgs = Func->FunctionFlags;
	Func->FunctionFlags |= 0x400;

	GetDefaultObj()->ProcessEvent(Func, &Parms);

	Func->FunctionFlags = Flgs;

	if (OutComparison != nullptr)
		*OutComparison = std::move(Parms.OutComparison);

	return Parms.ReturnValue;
}

